{"command":"kubectl create configmap nginx-temp-config --from-file=nginx.conf=cat <<EOF
user  nginx;
worker_processes  1;

events {
    worker_connections  1024;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    # Override default temporary directory to use writable volume
    client_temp  /var/data/client_temp;
    proxy_temp   /var/data/proxy_temp;
    fastcgi_temp /var/data/fastcgi_temp;

    server {
        listen 80;
        server_name localhost;
        root /usr/share/nginx/html;
        index index.html;
    }
}
EOF
"}

